<template>
  <div>
    <XotPfs ref="pfs"></XotPfs>
  </div>
</template>

<script>
import XotPfs from "../../components/XotPfs.vue"
import { flipToXot } from "../../utils/flipToXot";
export default {
  components: {
    XotPfs,
  },
  data() {
    return {
    }
  },
  mounted() {
    // 音频地址主要两个地方使用，题干中的url和口语资源包的url
    const resPath = JSON.parse(NetBrowser.getPageParams()).resPath;
    console.log(resPath, 'resPath');
    let _this = this;
    this.loadScript(`${resPath}page1.js`, function() {
      console.log(pageConfig, 'pageConfig');
      const questObj = flipToXot(pageConfig, resPath);
      console.log(questObj, 'questObj');
      _this.$refs.pfs.init({
        paperObj: questObj,
        isLine: true,
      });
    })
  },
  methods: {
    loadScript (url, callback) {
      var script = document.createElement("script");
      script.type = "text/javascript";
    　　if(typeof(callback) != "undefined"){
      　　if (script.readyState) {
          　　script.onreadystatechange = function () {
          　　if (script.readyState == "loaded" || script.readyState == "complete") {
            　　script.onreadystatechange = null;
            　　callback();
          　　}
    　　　　};
    　　} else {
          script.onload = function () {
            callback();
          };
        }
      }
      script.src = url;
      document.body.appendChild(script);
    }
  }
}
</script>

