
export function refreshRem (remUnit = 100) {
  var width = document.documentElement.getBoundingClientRect().width;
  let baseWidth = 1500;
  if ((width >= 1650 && width <= 2100) || width < 850) {
      width = baseWidth;
  } else if (width >= 1450 && width < 1650) {
      width = 1400;
  } else if (width >= 1050 && width < 1330) {
      width = 1330;
  } else if (width >= 850 && width < 1050) {
      width = 1200;
  }
  var rem = Math.ceil(width / baseWidth * remUnit);
  let dom = document.documentElement;
  dom.style.fontSize = rem + 'px';
  dom.setAttribute("data-dpr", Math.floor(rem / remUnit));
}
refreshRem();
window.addEventListener('resize', () => {
  refreshRem();
});
