const questionType = {
  combination: 99,
}

const flipKey = {
  record_follow_read: 'attachment',
  difficulty: 'difficulty',
  directions: 'directions',
  question_id: 'elementId',
  extends: 'extends', // 扩展字段，page1中没有
  knowledge: 'knowledge',
  options: 'options',
  question_kind: 'questionKind',
  question_no: 'questionNo',
  question_score: 'questionScore',
  question_text: 'questionText',
  questionTextCopy: 'questionTextCopy', // page1中没有
  question_type: 'questionType',
  ref_section_id: 'refSectionId',
  ref_sub_id: 'refSubId',
}

// 判断是否是对象
function isObject(any) {
  return Object.prototype.toString.call(any) === '[object Object]';
}

// 判断是否是数组
function isArray(any) {
  return Object.prototype.toString.call(any) === '[object Array]';
}

// 判断是否是组合题
function isCombination(obj) {
  if (!isObject(obj)) return console.error(obj + "不是一个对象，所以不是组合题的数据");
  return obj.question_id && obj.question_type && obj.question_type === questionType.combination;
}

// 判断是否是小题
function isQuestion(obj) {
  if (!isObject(obj)) return console.error(obj + "不是一个对象，所以不是小题的数据");
  return typeof obj.question_id !== "undefined" && obj.question_type !== questionType.combination;
}

// flag控制函数可复用，筛选出组合题中的小题
function dfs(nodes, flag = true) {
  let result = [];
  let stack = [];
  stack.push(...nodes);
  while(stack.length) {
      let node = stack.pop();
      if (isObject(node)) {
        if (isCombination(node) && flag) {
          result.push(node);
          continue;
        }
        if (isQuestion(node)) {
          result.push(node);
          continue;
        }
        stack.push(...Object.values(node))
      }
      if(isArray(node)) stack.push(...node);
  }
  return result;
}

// 改变数据结构
function structureChange(arr, url) {
  for (let i = 0; i < arr.length; i++){
    arr[i].url = url + `questions/${arr[i].question_id}/`;
    // 组合题
    if (arr[i].question_type == questionType.combination && arr[i].question_id) {
      arr[i] = combinationQuestChange(arr[i]);
    } else if (arr[i].question_id && typeof arr[i].question_type === 'number') { // 小题,这里是单选题
      arr[i] = smallQuestChange(arr[i]);
    }
  }
  return arr;
}

// 改变小题的数据结构（现在只用于单选题） flag = true代表是组合题下的小题
function smallQuestChange(question, refQuestionId) {
  let j = {};
  Object.keys(flipKey).forEach(key => {
    j[flipKey[key]] = question[key] || '';     
  });
  j.standardAnswerObj = {
    analysis: question.analysis,
    answerList: [],
    answerText: question.answer_text,
    elementId: question.question_id,
  };
  // 组合题小题中的id   指向组合题的id
  j.refQuestionId = refQuestionId ? refQuestionId : '';
  // 口语资源包类型
  let medias = question.medias;
  if (medias.length > 0 ) {
    if (medias[0].type === 'media') {
      // 地址由客户端绝对路径和file拼凑
      let soundfile = question.record_follow_read.mode_list[0].media_file;
      let url = question.url + (soundfile || medias[0].file);
      j.questionText = j.questionText + `<img media=\"audio\" src=\"/lib/xoteditorv2/dialogs/xotspoken/images/media.jpg\" url=\"${url}\" has_audio=\"false\" limit=\"-1\" guid=\"${NewGuid().ToString()}\">`;
      j = attachmentChange(j, question.url);
    }
  }
  if (refQuestionId) {
    j.refSubId = j.elementId;
    return j;
  }
  return {
    elementObj: j,
    id: j.elementId,
    type: '3',
  }
}

// 改变组合题的数据结构
function combinationQuestChange(question) {
  const j = {};
  j.id = question.question_id;
  j.isGroupText = '1',
  j.type = question.element_type,
  j.elementObj = {
    attachment: question.record_follow_read,
    elementId: question.question_id,
    elementText: question.elementText || '',
    modelTest: question.modelTest || '',
    questionScore: question.question_score,
    questionText: question.question_text, // 需要将音频处理成img，使全屏讲解可以渲染音频播放器
    questionTextCopy: question.questionTextCopy || '',
    questionType: question.question_type,
    refSectionId: question.refSectionId || '',
    subQuestions: dfs([question], false).map(i => smallQuestChange(i, question.question_id)),
  }
  let medias = question.medias;
  if (medias.length > 0 ) {
    if (medias[0].type === 'media') {
      let soundfile = question.record_follow_read.mode_list[0].media_file;
      let url = question.url + `questions/${question.question_id}/` + (soundfile || medias[0].file);
      j.elementObj.questionText = j.elementObj.questionText + `<img media=\"audio\" src=\"/lib/xoteditorv2/dialogs/xotspoken/images/media.jpg\" url=\"${url}\" has_audio=\"true\" limit=\"-1\" upload=\"true\" guid=\"${NewGuid().ToString()}\">`;
    }
  }

  j.elementObj.attachment = attachmentChange(j.elementObj, question.url);
  return j;
}

// 转换attachment的数据结构
function attachmentChange(question, url) {
  if (!question.attachment) return { ...question, attachment: '' };
  let media = question.attachment.mode_list[0];
  let paragraphs =  question.attachment.paragraph_list.map(i => ({
    pre: i.pre,
    sentences: i.sentences.map(k => ({
      id: k.id || '',
      content: k.keyNo ? `<b>${k.content_en}</b>` : k.content_en,
      netfiles: k.net_files || [],
      keyno: k.keyNo || '',
    }))
  }));
  const j = {
    baseUrl: url,
    paragraphs,
    sentenceTimes: media.sentences,
    soundfile: media.media_file,
  };
  if (question.questionType === questionType.combination) return j;
  return { ...question, attachment: j };
}

// Guid类
function Guid(g) {
  var arr = new Array(); //存放32位数值的数组
  if (typeof(g) == "string"){ //如果构造函数的参数为字符串
      InitByString(arr, g);
  }
  else{
      InitByOther(arr);
  }
  //返回一个值，该值指示 Guid 的两个实例是否表示同一个值。
  this.Equals = function(o){
      if (o && o.IsGuid){
          return this.ToString() == o.ToString();
      }
      else{
          return false;
      }
  }
  //Guid对象的标记
  this.IsGuid = function(){}
  //返回 Guid 类的此实例值的 String 表示形式。
  this.ToString = function(format){
      if(typeof(format) == "string"){
          if (format == "N" || format == "D" || format == "B" || format == "P"){
              return ToStringWithFormat(arr, format);
          }
          else{
              return ToStringWithFormat(arr, "D");
          }
      }
      else{
          return ToStringWithFormat(arr, "D");
      }
  }
  //由字符串加载
  function InitByString(arr, g){
      g = g.replace(/\{|\(|\)|\}|-/g, "");
      g = g.toLowerCase();
      if (g.length != 32 || g.search(/[^0-9,a-f]/i) != -1){
          InitByOther(arr);
      }
      else{
          for (var i = 0; i < g.length; i++){
              arr.push(g[i]);
          }
      }
  }
  //由其他类型加载
  function InitByOther(arr){
      var i = 32;
      while(i--){
          arr.push("0");
      }
  }
  /*
  根据所提供的格式说明符，返回此 Guid 实例值的 String 表示形式。
  N  32 位： xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
  D  由连字符分隔的 32 位数字 xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx
  B  括在大括号中、由连字符分隔的 32 位数字：{xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx}
  P  括在圆括号中、由连字符分隔的 32 位数字：(xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx)
  */
  function ToStringWithFormat(arr, format){
      switch(format){
          case "N":
              return arr.toString().replace(/,/g, "");
          case "D":
              var str = arr.slice(0, 8) + "-" + arr.slice(8, 12) + "-" + arr.slice(12, 16) + "-" + arr.slice(16, 20) + "-" + arr.slice(20,32);
              str = str.replace(/,/g, "");
              return str;
          case "B":
              var str = ToStringWithFormat(arr, "D");
              str = "{" + str + "}";
              return str;
          case "P":
              var str = ToStringWithFormat(arr, "D");
              str = "(" + str + ")";
              return str;
          default:
              return new Guid();
      }
  }
}

// 生成guid
function NewGuid(){
  Guid.Empty = new Guid();
  var g = "";
  var i = 32;
  while(i--){
      g += Math.floor(Math.random()*16.0).toString(16);
  }
  return new Guid(g);
};

export function flipToXot(obj, url) {
  if (!isObject(obj)) return console.error(obj + "数据不是一个对象");
  let nodes = Object.values(obj);
  const questionObj = structureChange(dfs(nodes), url);
  return questionObj.reverse();
}
