<template>
  <div>
  </div>
</template>

<script>
// xot引擎
/* eslint-disable */
import template from 'art-template/lib/template-web';
import videojs from 'video.js/dist/alt/video.core.min';
import $ from 'jquery/dist/jquery';
window.$ = $;
window.jQuery = $;
window.template = template;
window.videojs = videojs;
require('../lib/U3CompoLib-1.0.0/U3CompoLib');
import '../lib/xot/xot-pfs/build/preview-fullscreen';
let xotPfs = pfs.pfs;

import { refreshRem } from '../utils/flexible';
export default {
  name: "XotPfs",
  data() {
    return {
      isClose: false,
    }
  },
  mounted() {
    refreshRem();
  },
  methods: {
    bindEvent () {
      xotPfs.removeAllListeners('pfs-retry').on('pfs-retry', this.retry);
      xotPfs.removeAllListeners('pfs-close').on('pfs-close', this.closePfs);
      xotPfs.removeAllListeners('xotModalParams').on('xotModalParams',  this.eventRegistStatistics)
    },
    eventRegistStatistics(params) {
      this.$emit("openAnswerStatistic", params)
    },
    init (config) {
      this.bindEvent();

      this.isClose = false;
      xotPfs.removeAllListeners('pfs-closeLoading').on('pfs-closeLoading', () => {
          this.isClose = true;
      });
      xotPfs.showLoading();

      // 全屏讲解的默认设置
      /**
       * 电子白板pfs的配置选项对象
       * @param {Object} configOption 配置对象
       * @param {Array}  configOption.paperObj 试卷信息数组
       * @param {string} configOption.paperDataXML 试卷数据XML
       * @param {string} configOption.standardAnswerXML 标准答案数据XML
       * @param {string} configOption.userAnswerXML 用户答案数据XML
       * @param {string} configOption.markDataXML 批改数据XML
       * @param {string} configOption.cdnUrl CDN前缀
       * @param {string} configOption.elementId 小题ID(如果存在此参数, 电子白板首先会定位到该小题)
       * @param {boolean} configOption.isStatisticsSupport 是否支持作答统计
       * @param {string} [configOption.paperKey] 试卷唯一Id
       * @param {string} [configOption.resPrefix] 口语题中利用 resPrefix 来判断客户端情况决定是否播放本地口语原音
       * @param {Object} [configOption.studentInfo] 学生信息
       * @param {Object} [configOption.percentInfo] 得分率信息
       * @param {Object} [configOption.isSameQuestion] 是否支持同类题
       * @param {Object} [configOption.fromFlipBook] 是否在标准产品内进入的全屏讲解
       * @param {Object} [configOption.isSame] 是否通过点击同类题打开的全屏讲解
       * @param {Object} [configOption.isLine] 是否是离线模式
       */
      let pfsParams = Object.assign({ isSameQuestion: false, isStatisticsSupport: false }, config);
      if (!this.isClose) {
        xotPfs.init(pfsParams);
      }
    },
    getPfs () {
      return xotPfs;
    },
    retry () {
      this.init();
    },
    closePfs () {
      this.$emit('closePfs');
    }
  }
};
</script>

<style scoped lang="scss">
@import "../lib/xot/xot-pfs/build/preview.fullscreen.css";
@import "../lib/U3CompoLib-1.0.0/css/theme.css";
</style>
